def transform(grid):
    from itertools import permutations

    h, w = len(grid), len(grid[0])
    frames = set()

    for r1 in range(h):
        for c1 in range(w):
            color = grid[r1][c1]
            if color == 0:
                continue
            for c2 in range(c1 + 2, w):
                if grid[r1][c2] != color:
                    continue
                for r2 in range(r1 + 2, h):
                    if (grid[r2][c1] == color and grid[r2][c2] == color
                            and all(grid[r1][x] == color and grid[r2][x] == color
                                    for x in range(c1, c2 + 1))
                            and all(grid[y][c1] == color and grid[y][c2] == color
                                    for y in range(r1, r2 + 1))):
                        frames.add((r1, r2, c1, c2, color))

    frames = sorted(frames)
    if not frames:
        return [row[:] for row in grid]

    border = set()
    out = [[0] * w for _ in range(h)]
    targets = []
    for r1, r2, c1, c2, color in frames:
        for x in range(c1, c2 + 1):
            border.add((r1, x))
            border.add((r2, x))
            out[r1][x] = color
            out[r2][x] = color
        for y in range(r1, r2 + 1):
            border.add((y, c1))
            border.add((y, c2))
            out[y][c1] = color
            out[y][c2] = color

        targets.append(sum(
            1 for y in range(r1 + 1, r2) for x in range(c1 + 1, c2)
            if (y - r1 - 1 + x - c1 - 1) % 2 == 0
        ))

    counts = {}
    frame_colors = {f[4] for f in frames}
    for y in range(h):
        for x in range(w):
            color = grid[y][x]
            if color and color not in frame_colors and (y, x) not in border:
                counts[color] = counts.get(color, 0) + 1

    colors = list(counts)
    best = None
    if len(colors) >= len(frames):
        for choice in permutations(colors, len(frames)):
            score = sum(abs(counts[c] - targets[i]) for i, c in enumerate(choice))
            if best is None or score < best[0]:
                best = (score, choice)

    if best:
        for (r1, r2, c1, c2, _), fill in zip(frames, best[1]):
            for y in range(r1 + 1, r2):
                for x in range(c1 + 1, c2):
                    if (y - r1 - 1 + x - c1 - 1) % 2 == 0:
                        out[y][x] = fill

    return out
